<?php
use App\Http\Controllers\Admin\AboutSettingController; use App\Http\Controllers\Admin\CoreValueController; use App\Http\Controllers\Admin\LeaderController; use App\Http\Controllers\Admin\ServiceTimeController; use App\Models\AboutSetting; use App\Models\CoreValue; use App\Models\Leader; use App\Models\ServiceTime; use Illuminate\Support\Facades\Route;
Route::get('/about',fn()=>view('pages.about',['aboutSetting'=>AboutSetting::current(),'coreValues'=>CoreValue::where('is_published',1)->orderBy('sort_order')->get(),'leaders'=>Leader::where('is_published',1)->orderBy('sort_order')->get()]))->name('about');
Route::get('/about/motto',fn()=>view('pages.motto',['aboutSetting'=>AboutSetting::current()]))->name('about.motto');
Route::get('/plan-your-visit',fn()=>view('pages.visit',['serviceTimes'=>ServiceTime::where('is_published',1)->orderBy('sort_order')->get()]))->name('visit');
Route::get('/service-times',fn()=>view('pages.service-times',['serviceTimes'=>ServiceTime::where('is_published',1)->orderBy('sort_order')->get()]))->name('service-times');
Route::middleware(['auth','role:super_admin,senior_pastor,admin,media_team'])->prefix('admin')->name('admin.')->group(function(){Route::get('about-settings',[AboutSettingController::class,'edit'])->name('about-settings.edit');Route::put('about-settings',[AboutSettingController::class,'update'])->name('about-settings.update');Route::resource('core-values',CoreValueController::class)->except('show');Route::resource('leaders',LeaderController::class)->except('show');Route::resource('service-times',ServiceTimeController::class)->except('show');});
